export function localizeRiderCard<T extends Partial<RiderCard> & { id: string; name: string; keys: string[]; general: string; love: string; work: string; money: string; growth: string; advice: string; symbols?: string; reversed: string }>(card: T, lang: Language): T {
  if (lang === "ES") return card;
  const translation = riderCardTranslations[card.id]?.[lang];
  if (!translation) return card;
  return {
    ...card,
    name: translation.name,
    keys: translation.keys,
    general: translation.general,
    love: translation.love,
    work: translation.work,
    money: translation.money,
    growth: translation.growth,
    advice: translation.advice,
    symbols: translation.symbols ?? card.symbols,
    reversed: translation.reversed,
  };
}
